<style>
	.logo-wall-section {
		background: var(--dk-bg-deep);
		overflow: hidden;
		position: relative;
	}

	.logo-wall-section::before,
	.logo-wall-section::after {
		content: "";
		position: absolute;
		top: 0;
		bottom: 0;
		width: 15%;
		min-width: 150px;
		z-index: 10;
		pointer-events: none;
	}

	.logo-wall-section::before {
		left: 0;
		background: linear-gradient(to right, var(--dk-bg-deep) 10%, transparent);
	}

	.logo-wall-section::after {
		right: 0;
		background: linear-gradient(to left, var(--dk-bg-deep) 10%, transparent);
	}

	.logo-wall-divider {
		height: 1px;
		background: var(--dk-border);
		width: 100%;
		position: relative;
		z-index: 20;
	}

	.marquee-container {
		width: 100%;
		overflow: hidden;
		position: relative;
	}

	.marquee-content {
		display: flex;
		align-items: stretch;
		width: max-content;
		animation: scroll 60s linear infinite;
	}

	.marquee-content:hover {
		animation-play-state: paused;
	}

	@keyframes scroll {
		0% {
			transform: translateX(0);
		}
		100% {
			transform: translateX(-50%);
		}
	}

	.logo-item {
		display: flex;
		align-items: center;
		justify-content: center;
		gap: 12px;
		padding: 32px 24px;
		width: 220px;
		color: var(--dk-text-muted);
		opacity: 0.6;
		transition: opacity 0.25s ease, color 0.25s ease;
		border-right: 1px solid var(--dk-border);
	}

	.logo-item:hover {
		opacity: 1;
		color: var(--dk-text-muted); /* Maintained to match your request */
	}

	.logo-item :global(svg) {
		width: 28px;
		height: 28px;
		display: block;
	}
	
	.logo-item :global(svg path[fill]:not([fill="none"])) {
		fill: currentColor;
	}

	.logo-name {
		font-family: 'Inter', sans-serif;
		font-weight: 500;
		font-size: 16px;
		white-space: nowrap;
	}
	
	@media (max-width: 768px) {
		.logo-item {
			padding: 24px 16px;
			width: 180px;
		}
		.logo-item :global(svg) {
			width: 24px;
			height: 24px;
		}
		.logo-name {
			font-size: 14px;
		}
	}
</style>
